pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }
    function testFuzz_property(uint256 val1, uint256 val2) public {
        c.Initialized();

        uint256 minSumBefore = c.MinSum();

        try c.SetMinSum(val1) {
            uint256 minSumAfter = c.MinSum();
            assertTrue(minSumAfter == minSumBefore);
        } catch {
            assertTrue(c.MinSum() == minSumBefore);
        }
    }
}
